# Let me think about this systematically by seeing what happens with different orders
inputs = ['uhde', 'yby', 'vcbb', 'xe', 'ggvh']
outputs = ['uheve', 'wevauyiwev', 'vcauyiauyi', 'je', 'ggvh']

# What if I try to build up the solution step by step?
# First, let me try to see if there's a pattern in how characters are transformed

# Looking at all transformations together:
print("Character transformations needed:")
transformations = {}
for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            if inp[i] not in transformations:
                transformations[inp[i]] = outp[i]
            else:
                # If we already saw this transformation, it might be complex
                pass
    # Handle length differences
    if len(inp) < len(outp):
        # Characters were added - let's note positions
        for i in range(len(inp), len(outp)):
            print(f"Added character '{outp[i]}' at position {i}")

print("Character to character mappings:")
for char, replacement in transformations.items():
    print(f"'{char}' -> '{replacement}'")

# Also let's check if any characters are removed
for inp, outp in zip(inputs, outputs):
    if len(inp) > len(outp):
        print(f"Removed characters from '{inp}' to get '{outp}'")

